function evalRPN(tokens) {
    const stack = [];
    const ops = new Set(['+', '-', '*', '/']);
    for (const token of tokens) {
        if (ops.has(token)) {
            const b = stack.pop();
            const a = stack.pop();
            if (token === '+') stack.push(a + b);
            else if (token === '-') stack.push(a - b);
            else if (token === '*') stack.push(a * b);
            else stack.push(Math.trunc(a / b));
        } else {
            stack.push(parseInt(token));
        }
    }
    return stack[0];
}

