function longestConsecutive(nums) {
    const numSet = new Set(nums);
    let maxLen = 0;
    for (const num of numSet) {
        if (!numSet.has(num - 1)) {
            let current = num;
            let length = 1;
            while (numSet.has(current + 1)) {
                current++;
                length++;
            }
            maxLen = Math.max(maxLen, length);
        }
    }
    return maxLen;
}

